"""Export immutable Map Creator tables from the unchanged reference constants."""
from pathlib import Path
import importlib,json,sys
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT))
c=vars(importlib.import_module('shared.constants'))
p=vars(importlib.import_module('shared.constants_prefabs'))
def q(s):return json.dumps(s,ensure_ascii=False)
rows=['// SPDX-License-Identifier: AGPL-3.0-or-later','// Generated by tools/export_ugc_catalog.py from the reference constants.','package net.battlespades.ugc;','import java.util.*;','public final class UgcCatalog {','    private UgcCatalog(){}','    public static final List<String> ITEMS=List.of('+','.join(q(c['UGC_TOOL_IMAGES'][i])for i in range(19))+');','    public static final Map<String,Set<Integer>> PREFABS=load();','    private static Map<String,Set<Integer>> load(){var result=new LinkedHashMap<String,Set<Integer>>();']
for name,tags in p['PREFABS_NAMES_WITH_TAGS'].items():rows.append('        result.put('+q(name)+',Set.of('+','.join(map(str,dict.fromkeys(tags)))+'));')
rows+=['        return Collections.unmodifiableMap(result);','    }','    public static final Map<String,Integer> FOG=Map.ofEntries(' + ','.join('Map.entry('+q(name)+','+str((rgb[0]<<16)|(rgb[1]<<8)|rgb[2])+')'for name,rgb in c['FOG_COLORS'].items())+');','}']
out=ROOT/'java/src/main/java/net/battlespades/ugc/UgcCatalog.java';out.parent.mkdir(parents=True,exist_ok=True);out.write_text('\n'.join(rows)+'\n')
print(f'Exported {len(p["PREFABS_NAMES_WITH_TAGS"])} prefab definitions and 19 editor items')
